// ════════════════════════════════════════════════════════════════════════
// MémoTruck — Export PDF
// Utilise jsPDF + jspdf-autotable (chargés via CDN dans index.html)
// ════════════════════════════════════════════════════════════════════════

const LOGO_B64 = "data:image/png;base64,";

function _getPDF() {
  const { jsPDF } = window.jspdf;
  return new jsPDF({ orientation: "portrait", unit: "mm", format: "a4" });
}

function _entete(doc, titre, sousTitre = "") {
  // Bandeau header
  doc.setFillColor(15, 25, 35);
  doc.rect(0, 0, 210, 22, "F");

  // Logo
  doc.addImage(LOGO_B64, "PNG", 8, 2, 18, 18);

  // Nom app
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(14);
  doc.setFont("helvetica", "bold");
  doc.text("MEMOTRUCK", 30, 10);

  doc.setFontSize(9);
  doc.setFont("helvetica", "normal");
  doc.text(`Exporté le ${new Date().toLocaleDateString("fr-FR")} à ${new Date().toLocaleTimeString("fr-FR", { hour: "2-digit", minute: "2-digit" })}`, 30, 17);

  // Titre section
  doc.setTextColor(15, 25, 35);
  doc.setFontSize(16);
  doc.setFont("helvetica", "bold");
  doc.text(titre, 14, 34);

  if (sousTitre) {
    doc.setFontSize(10);
    doc.setFont("helvetica", "normal");
    doc.setTextColor(100, 100, 100);
    doc.text(sousTitre, 14, 41);
  }

  return sousTitre ? 48 : 42;
}

function _tableau(doc, startY, head, body, couleurHeader = [0, 194, 255]) {
  doc.autoTable({
    startY,
    head: [head],
    body,
    theme: "grid",
    headStyles: {
      fillColor: couleurHeader,
      textColor: [255, 255, 255],
      fontStyle: "bold",
      fontSize: 9
    },
    bodyStyles:     { fontSize: 8, textColor: [30, 30, 30] },
    alternateRowStyles: { fillColor: [245, 248, 250] },
    margin: { left: 14, right: 14 },
    tableWidth: "auto"
  });
}

function _save(doc, nom) {
  const date = new Date().toISOString().substring(0, 10);
  doc.save(`memotruck_${nom}_${date}.pdf`);
}

// ─── Export Consommations ─────────────────────────────────────────────────

export function exportConsommationsPDF(rows, chauffeursMap, titre = "Suivi consommations") {
  const doc = _getPDF();
  const startY = _entete(doc, titre);

  // Stats résumé
  const totalKm  = rows.reduce((a, r) => a + Number(r.kilometres || 0), 0);
  const totalL   = rows.reduce((a, r) => a + Number(r.litres || 0), 0);
  const moy      = rows.length ? rows.reduce((a, r) => a + Number(r.valeur || 0), 0) / rows.length : 0;

  doc.setFontSize(9);
  doc.setFont("helvetica", "normal");
  doc.setTextColor(80, 80, 80);
  doc.text(`${rows.length} saisies · ${Math.round(totalKm).toLocaleString("fr-FR")} km · ${totalL.toFixed(0)} L · Moy: ${moy.toFixed(1)} L/100`, 14, startY - 4);

  const head = ["DATE", "TRACTEUR", "REMORQUE", "CHAUFFEUR", "KM", "LITRES", "L/100"];
  const body = rows.map(r => [
    r.date ? new Date(r.date).toLocaleDateString("fr-FR") : "—",
    r.plaque_tracteur || "—",
    r.plaque_remorque || "Solo",
    chauffeursMap[r.chauffeur_id] || "—",
    Math.round(r.kilometres || 0).toLocaleString("fr-FR"),
    (r.litres || 0).toFixed(1),
    (r.valeur || 0).toFixed(1)
  ]);

  _tableau(doc, startY, head, body);
  _save(doc, "consommations");
}

// ─── Export Chauffeurs ────────────────────────────────────────────────────

export function exportChauffeursPDF(rows) {
  const doc = _getPDF();
  const startY = _entete(doc, "Liste des chauffeurs", `${rows.length} chauffeur(s)`);

  const head = ["NOM", "PRÉNOM", "EMAIL", "CARTE COND.", "VISITE MÉD.", "FCO", "ADR"];
  const body = rows.map(r => [
    r.nom || "—",
    r.prenom || "—",
    r.email || "—",
    r.date_carte_conducteur ? new Date(r.date_carte_conducteur).toLocaleDateString("fr-FR") : "—",
    r.date_visite_medicale  ? new Date(r.date_visite_medicale).toLocaleDateString("fr-FR")  : "—",
    r.date_fco              ? new Date(r.date_fco).toLocaleDateString("fr-FR")              : "—",
    r.date_adr              ? new Date(r.date_adr).toLocaleDateString("fr-FR")              : "—"
  ]);

  _tableau(doc, startY, head, body, [0, 150, 200]);
  _save(doc, "chauffeurs");
}

// ─── Export Véhicules ─────────────────────────────────────────────────────

export function exportVehiculesPDF(tracteurs, remorques) {
  const doc = _getPDF();
  let startY = _entete(doc, "Parc véhicules", `${tracteurs.length} tracteur(s) · ${remorques.length} remorque(s)`);

  // Tracteurs
  doc.setFontSize(11);
  doc.setFont("helvetica", "bold");
  doc.setTextColor(15, 25, 35);
  doc.text("Tracteurs / Porteurs", 14, startY);
  startY += 4;

  const headT = ["PLAQUE", "PROFIL", "MARQUE", "MODÈLE", "CT", "ASSURANCE", "LIMITEUR", "CHRONO"];
  const bodyT = tracteurs.map(t => [
    t.plaque || "—",
    t.profil  || "—",
    t.marque  || "—",
    t.modele  || "—",
    t.date_ct                ? new Date(t.date_ct).toLocaleDateString("fr-FR")                : "—",
    t.date_assurance         ? new Date(t.date_assurance).toLocaleDateString("fr-FR")         : "—",
    t.date_limiteur_vitesse  ? new Date(t.date_limiteur_vitesse).toLocaleDateString("fr-FR")  : "—",
    t.date_chronotachygraphe ? new Date(t.date_chronotachygraphe).toLocaleDateString("fr-FR") : "—"
  ]);
  _tableau(doc, startY, headT, bodyT, [0, 194, 255]);

  // Remorques
  startY = doc.lastAutoTable.finalY + 10;
  doc.setFontSize(11);
  doc.setFont("helvetica", "bold");
  doc.setTextColor(15, 25, 35);
  doc.text("Remorques", 14, startY);
  startY += 4;

  const headR = ["PLAQUE", "PROFIL", "MARQUE", "MODÈLE", "CT", "ASSURANCE"];
  const bodyR = remorques.map(r => [
    r.plaque  || "—",
    r.profil  || "—",
    r.marque  || "—",
    r.modele  || "—",
    r.date_ct        ? new Date(r.date_ct).toLocaleDateString("fr-FR")        : "—",
    r.date_assurance ? new Date(r.date_assurance).toLocaleDateString("fr-FR") : "—"
  ]);
  _tableau(doc, startY, headR, bodyR, [100, 100, 200]);
  _save(doc, "vehicules");
}

// ─── Export Interventions ─────────────────────────────────────────────────

const STATUT_LABEL_PDF = { a_faire: "À faire", pris_en_charge: "Pris en charge", termine: "Terminé" };

export function exportInterventionsPDF(rows, chauffeursMap, titre = "Historique interventions", enginsMap = {}) {
  const doc = _getPDF();
  const startY = _entete(doc, titre, `${rows.length} intervention(s)`);

  const hasAtelierStatuts = rows.some(r => !!r.statut);
  const head = hasAtelierStatuts
    ? ["DATE", "VÉHICULE", "CHAUFFEUR", "TYPE", "DÉTAILS", "STATUT", "COMMENTAIRE MÉCANO"]
    : ["DATE", "VÉHICULE", "CHAUFFEUR", "TYPE", "DÉTAILS"];
  const body = rows.map(r => {
    const vehicule = r.entite_type === "engin" ? (enginsMap[r.entite_plaque] || r.entite_plaque) : r.entite_plaque;
    const base = [
      r.date ? new Date(r.date).toLocaleDateString("fr-FR") : "—",
      vehicule || "—",
      chauffeursMap[r.chauffeur_id] || "—",
      r.type || "—",
      (r.details || "").substring(0, 40)
    ];
    if (hasAtelierStatuts) {
      base.push(r.statut ? (STATUT_LABEL_PDF[r.statut] || r.statut) : "—");
      base.push((r.commentaire_mecanicien || "—").substring(0, 40));
    }
    return base;
  });

  _tableau(doc, startY, head, body, [239, 68, 68]);
  _save(doc, "interventions");
}

// ─── Export Historique Attelages ──────────────────────────────────────────

export function exportAttelagesPDF(rows, chauffeursMap, titre = "Historique attelages") {
  const doc = _getPDF();
  const startY = _entete(doc, titre, `${rows.length} attelage(s)`);

  const totalKm = rows.reduce((s, r) => s + Number(r.km_parcourus || 0), 0);
  doc.setFontSize(9);
  doc.setFont("helvetica", "normal");
  doc.setTextColor(80, 80, 80);
  doc.text(`Total km : ${Math.round(totalKm).toLocaleString("fr-FR")} km`, 14, startY - 4);

  const head = ["DATE", "CHAUFFEUR", "TRACTEUR", "REMORQUE", "PROFIL", "KM", "FIN"];
  const body = rows.map(r => [
    r.date_debut ? new Date(r.date_debut).toLocaleDateString("fr-FR") : "—",
    chauffeursMap[r.chauffeur_id] || "—",
    r.plaque_tracteur || "—",
    r.plaque_remorque || "Solo",
    r.profil_moteur   || "—",
    r.km_parcourus > 0 ? Math.round(r.km_parcourus).toLocaleString("fr-FR") + " km" : "—",
    r.date_fin ? new Date(r.date_fin).toLocaleDateString("fr-FR") : "En cours"
  ]);

  _tableau(doc, startY, head, body, [16, 185, 129]);
  _save(doc, "attelages");
}

// ─── Export Pneumatiques ──────────────────────────────────────────────────

export function exportPneumatiquesPDF(tracteurs, remorques) {
  const doc = _getPDF();
  let startY = _entete(doc, "Suivi pneumatiques");

  // Tracteurs
  doc.setFontSize(11);
  doc.setFont("helvetica", "bold");
  doc.setTextColor(15, 25, 35);
  doc.text("Tracteurs / Porteurs", 14, startY);
  startY += 4;

  const headT = ["PLAQUE", "MARQUE", "POSE AVANT", "POSE ARRIÈRE"];
  const bodyT = tracteurs.map(t => [
    t.plaque || "—",
    `${t.marque || ""} ${t.modele || ""}`.trim() || "—",
    t.date_pose_avant   ? new Date(t.date_pose_avant).toLocaleDateString("fr-FR")   : "—",
    t.date_pose_arriere ? new Date(t.date_pose_arriere).toLocaleDateString("fr-FR") : "—"
  ]);
  _tableau(doc, startY, headT, bodyT, [0, 194, 255]);

  // Remorques
  startY = doc.lastAutoTable.finalY + 10;
  doc.setFontSize(11);
  doc.setFont("helvetica", "bold");
  doc.setTextColor(15, 25, 35);
  doc.text("Remorques", 14, startY);
  startY += 4;

  const headR = ["PLAQUE", "MARQUE", "E1", "E2", "E3"];
  const bodyR = remorques.map(r => [
    r.plaque || "—",
    `${r.marque || ""} ${r.modele || ""}`.trim() || "—",
    r.date_pose_e1 ? new Date(r.date_pose_e1).toLocaleDateString("fr-FR") : "—",
    r.date_pose_e2 ? new Date(r.date_pose_e2).toLocaleDateString("fr-FR") : "—",
    r.date_pose_e3 ? new Date(r.date_pose_e3).toLocaleDateString("fr-FR") : "—"
  ]);
  _tableau(doc, startY, headR, bodyR, [100, 100, 200]);
  _save(doc, "pneumatiques");
}

// ─── Export Dossier de conformité (documents d'un véhicule, d'un chauffeur,
// ou d'un dossier combiné mêlant les deux) ──────────────────────────────────
// entite:    { identifiant, sousTitre } — identifiant = plaque, nom du
//            chauffeur, ou "Nom + Plaque" pour un dossier combiné
// dateItems: [{ label, date, statut, groupe? }]  (statut = texte déjà
//            formaté, ex: "Expiré depuis 4j" — jamais d'emoji : la police
//            standard de jsPDF ne les rend pas (caractères illisibles dans
//            le PDF) ; groupe = nom de la section pour un dossier combiné,
//            ex: "Tracteur / Porteur — AB-123-CD" — absent = pas de
//            sous-titre, cas normal d'un dossier simple à une seule entité)
// photos:    [{ label, base64, width, height, groupe? }]  (base64/width/
//            height déjà résolus côté appelant)
// infos:     [{ label, valeur, groupe? }]  (coordonnées type adresse/
//            téléphone — texte simple, pas de date/statut)

// Regroupe une liste d'items par leur champ "groupe" pour l'affichage dans
// le PDF (un seul groupe implicite si absent ou si une seule entité).
function _grouperItems(items) {
  const noms = [...new Set(items.map((i) => i.groupe).filter(Boolean))];
  if (noms.length <= 1) return [{ nom: null, items }];
  const groupes = noms.map((nom) => ({ nom, items: items.filter((i) => i.groupe === nom) }));
  const sansGroupe = items.filter((i) => !i.groupe);
  if (sansGroupe.length) groupes.push({ nom: null, items: sansGroupe });
  return groupes;
}

export function exportDossierPDF(entite, dateItems, photos, infos = []) {
  const doc = _getPDF();
  let startY = _entete(doc, `Dossier — ${entite.identifiant}`, entite.sousTitre || "");

  if (infos.length > 0) {
    _grouperItems(infos).forEach((g) => {
      if (g.nom) {
        if (startY > 270) { doc.addPage(); startY = 20; }
        doc.setFontSize(11);
        doc.setFont("helvetica", "bold");
        doc.setTextColor(15, 25, 35);
        doc.text(g.nom, 14, startY);
        startY += 6;
      }
      g.items.forEach((info) => {
        if (startY > 285) { doc.addPage(); startY = 20; }
        doc.setFontSize(10);
        doc.setFont("helvetica", "bold");
        doc.setTextColor(90, 90, 90);
        doc.text(`${info.label} :`, 14, startY);
        doc.setFont("helvetica", "normal");
        doc.setTextColor(15, 25, 35);
        doc.text(String(info.valeur || "—"), 55, startY);
        startY += 6;
      });
      startY += 4;
    });
  }

  const head = ["DOCUMENT", "DATE LIMITE", "STATUT"];
  _grouperItems(dateItems).forEach((g) => {
    if (g.nom) {
      if (startY > 270) { doc.addPage(); startY = 20; }
      doc.setFontSize(11);
      doc.setFont("helvetica", "bold");
      doc.setTextColor(15, 25, 35);
      doc.text(g.nom, 14, startY);
      startY += 6;
    }
    const body = g.items.map(d => [
      d.label,
      d.date ? new Date(d.date).toLocaleDateString("fr-FR") : "—",
      d.statut || "—"
    ]);
    _tableau(doc, startY, head, body);
    startY = doc.lastAutoTable.finalY + 10;
  });

  const photosValides = (photos || []).filter(p => p.base64);
  if (photosValides.length > 0) {
    if (startY > 270) { doc.addPage(); startY = 20; }
    doc.setFontSize(12);
    doc.setFont("helvetica", "bold");
    doc.setTextColor(15, 25, 35);
    doc.text("Documents joints", 14, startY);
    startY += 8;

    const maxW = 182, maxH = 150;
    _grouperItems(photosValides).forEach((g) => {
      if (g.nom) {
        if (startY + 10 > 290) { doc.addPage(); startY = 20; }
        doc.setFontSize(10.5);
        doc.setFont("helvetica", "bolditalic");
        doc.setTextColor(80, 80, 80);
        doc.text(g.nom, 14, startY);
        startY += 6;
      }
      g.items.forEach((p) => {
        let w = maxW, h = (p.width && p.height) ? maxW * (p.height / p.width) : 100;
        if (h > maxH) { h = maxH; w = p.height ? maxH * (p.width / p.height) : maxW; }

        if (startY + h + 14 > 290) { doc.addPage(); startY = 20; }

        doc.setFontSize(10);
        doc.setFont("helvetica", "bold");
        doc.setTextColor(15, 25, 35);
        doc.text(p.label, 14, startY);
        startY += 5;
        try { doc.addImage(p.base64, "JPEG", 14, startY, w, h, undefined, "FAST"); } catch (_) {}
        startY += h + 10;
      });
    });
  }

  _save(doc, `dossier_${entite.identifiant}`);
}
